export default function TasksPage() { return <main><h1>Tasks</h1></main>; }

export default async function TaskPage({ params }: { params: Promise<{ id: string }> }) {
  const { id } = await params;
  return <h1>Task {id}</h1>;
}

import Link from "next/link";
export function TaskRow({ id, title }: { id: string; title: string }) {
  return <Link href={`/tasks/${id}`}>{title}</Link>;
}

export default async function TasksPage() {
  const tasks = await getTasksOnServer();
  return <ul>{tasks.map(task => <li key={task.id}>{task.title}</li>)}</ul>;
}

"use client";
import { useState } from "react";
export function TaskFilter() {
  const [query, setQuery] = useState("");
  return <input value={query} onChange={e => setQuery(e.target.value)} />;
}

// Server component
export default async function Page() {
  const tasks = await getTasksOnServer();
  return <TaskFilterClient initialTasks={tasks} />;
}

