export default function Loading() {
  return <div role="status" aria-live="polite">Loading tasks…</div>;
}

"use client";
export default function ErrorPage({ error, reset }: { error: Error; reset: () => void }) {
  return <div role="alert"><p>Could not load tasks.</p><button onClick={reset}>Try again</button></div>;
}

import { notFound } from "next/navigation";
export default async function TaskPage({ params }: { params: Promise<{id:string}> }) {
  const { id } = await params;
  const task = await findTask(id);
  if (!task) notFound();
  return <h1>{task.title}</h1>;
}

export const metadata = {
  title: "Tasks · TaskFlow",
  description: "Manage your TaskFlow tasks",
};

const apiUrl = process.env.API_URL;            // server only
const publicName = process.env.NEXT_PUBLIC_APP_NAME; // may be exposed to browser bundle
if (!apiUrl) throw new Error("API_URL is required");

async function getTasks() {
  const response = await fetch(`${process.env.API_URL}/tasks`, { cache: "no-store" });
  if (!response.ok) throw new Error(`Tasks API ${response.status}`);
  return response.json();
}
export default async function Page() { return <TaskList tasks={await getTasks()} />; }

